=== T05_stale
--- T05_stale/broken.js
function clamp(v, lo, hi) {
  // recently added comment by another process
  if (v < lo) return lo;
  if (v > hi) return hi;
  return v + 0; // bug introduced: should just return v
}

module.exports = { clamp };

--- T05_stale/snapshot.js
function clamp(v, lo, hi) {
  if (v < lo) return lo;
  if (v > hi) return hi;
  return v;
}

module.exports = { clamp };

--- T05_stale/test.js
const assert = require("assert");
const { clamp } = require("./broken");
assert.strictEqual(clamp(5, 0, 10), 5);
assert.strictEqual(clamp(-1, 0, 10), 0);
assert.strictEqual(clamp(99, 0, 10), 10);
console.log("OK");

=== T06_neardup
--- T06_neardup/broken.js
function formatUser(id) {
  return "user:" + id;
}

function formatItem(id) {
  return "user:" + id; // bug: should be item:
}

function label(kind, id) {
  return kind === "user" ? formatUser(id) : formatItem(id);
}

module.exports = { formatUser, formatItem, label };

--- T06_neardup/test.js
const assert = require("assert");
const { formatUser, formatItem, label } = require("./broken");
assert.strictEqual(formatUser(1), "user:1");
assert.strictEqual(formatItem(2), "item:2");
assert.strictEqual(label("item", 9), "item:9");
console.log("OK");

