cat > N01_median/broken.js <<'EOF'
// Small stats helpers used by the nightly report.
function sortNums(arr) {
  return arr.slice().sort((a, b) => a - b);
}

function mean(arr) {
  return arr.reduce((s, x) => s + x, 0) / arr.length;
}

function median(arr) {
  const s = sortNums(arr);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

module.exports = { sortNums, mean, median };
EOF
cat > N02_duration/broken.js <<'EOF'
// Parses durations like "1h30m", "45m", "2h", "90s", "1h2m3s" into seconds.
function parseDuration(str) {
  const re = /(\d+)([hms])/g;
  let total = 0;
  let m;
  while ((m = re.exec(str)) !== null) {
    const n = parseInt(m[1], 10);
    if (m[2] === "h") total += n * 3600;
    else if (m[2] === "m") total += n * 60;
    else total += n;
  }
  return total;
}

module.exports = { parseDuration };
EOF
cat > N03_csv/broken.js <<'EOF'
// Minimal CSV reader for the billing export.
// Handles double-quoted fields, including commas and "" escapes inside quotes.
function parseLine(line) {
  const cells = [];
  let cur = "";
  let quoted = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (quoted) {
      if (ch === '"' && line[i + 1] === '"') { cur += '"'; i++; }
      else if (ch === '"') quoted = false;
      else cur += ch;
    } else if (ch === '"') {
      quoted = true;
    } else if (ch === ",") {
      cells.push(cur);
      cur = "";
    } else {
      cur += ch;
    }
  }
  cells.push(cur);
  return cells;
}

function parseCsv(text) {
  const lines = text.trim().split("\n");
  const header = parseLine(lines[0]);
  return lines.slice(1).map((l) => {
    const cells = parseLine(l);
    const row = {};
    header.forEach((h, i) => (row[h] = cells[i]));
    return row;
  });
}

module.exports = { parseLine, parseCsv };
EOF
